<?php
namespace App\Livewire\Admin;
use App\Models\RetentionPolicy;use Livewire\Attributes\Layout;use Livewire\Component;use Livewire\WithPagination;
#[Layout('layouts.app')]
class RetentionPolicies extends Component{use WithPagination;public string $code='',$name='';public ?int $years=null;public bool $permanent=false;public function mount():void{abort_unless(app(\App\Domain\Authorization\Services\PermissionResolver::class)->allows(auth()->user(),'system.configure'),403);}public function save():void{$data=$this->validate(['code'=>['required','string','max:60','regex:/^[A-Z0-9_\-]+$/'],'name'=>['required','string','max:180'],'years'=>['nullable','integer','min:1','max:500'],'permanent'=>['boolean']]);if(!$data['permanent']&&!$data['years']){$this->addError('years','Retention years are required unless records are retained permanently.');return;}RetentionPolicy::create(['code'=>$data['code'],'name'=>$data['name'],'retention_years'=>$data['permanent']?null:$data['years'],'retain_permanently'=>$data['permanent'],'requires_disposition_approval'=>true,'is_active'=>true]);$this->reset(['code','name','years','permanent']);}public function render(){return view('livewire.admin.retention-policies',['policies'=>RetentionPolicy::latest()->paginate(25)]);}}
